import time
import urllib.request
from urllib.error import URLError, HTTPError

class RateLimitError(Exception):
    pass

class ServerError(Exception):
    pass

class ClientError(Exception):
    pass

class ConnectionError(Exception):
    pass

class APIClient:
    def __init__(self, base_url, timeout=10):
        self.base_url = base_url.rstrip('/')
        self.timeout = timeout

    def get(self, path):
        url = f"{self.base_url}{path}"

        # Retry logic for network errors (URLError)
        for attempt in range(2):
            try:
                with urllib.request.urlopen(url, timeout=self.timeout) as response:
                    return self._handle_response(response)
            except URLError as e:
                if attempt == 0:
                    time.sleep(1)
                else:
                    raise ConnectionError(f"Network error after retries: {e}") from e

        # This line is unreachable but needed for type checking
        raise ConnectionError("Unexpected flow")

    def _handle_response(self, response):
        status_code = response.status

        if status_code == 429:
            # Retry up to 3 times with exponential backoff
            for retry in range(3):
                backoff = 0.5 * (2 ** retry)
                time.sleep(backoff)
                try:
                    with urllib.request.urlopen(response.geturl(), timeout=self.timeout) as new_response:
                        return self._handle_response(new_response)
                except HTTPError as e:
                    if e.code == 429:
                        continue
                    # If we get a different status code, handle it
                    return self._handle_response(e)
                except URLError:
                    # Treat network error as 429 retry scenario
                    continue

            raise RateLimitError("Rate limit exceeded after retries")

        elif 500 <= status_code < 600:
            # Retry once after 1s
            time.sleep(1)
            try:
                with urllib.request.urlopen(response.geturl(), timeout=self.timeout) as new_response:
                    return self._handle_response(new_response)
            except HTTPError as e:
                if 500 <= e.code < 600:
                    raise ServerError(f"Server error: {e.code}") from e
                return self._handle_response(e)
            except URLError:
                raise ServerError("Server error: connection failed") from None

        elif 400 <= status_code < 500:
            raise ClientError(f"Client error: {status_code}")

        elif status_code >= 300:
            # Other redirect or client/server issues not explicitly handled
            raise ClientError(f"Unexpected status code: {status_code}")

        # 2xx success
        return response.read().decode('utf-8')
